def('lightning', () => [bolt('hi', 30, 8, 1.35), bolt('bs', 44, 20, .55)]);
def('thunder',() => [bolt('lo', 22, 10, .8),
                     ...[13, 20, 27].map((rad, i) =>                 // the sound going out
                       ['s', `M${n(38 - rad * .35)} ${n(34 - rad)} A${rad} ${rad} 0 0 1 ${n(38 - rad * .35)} ${n(34 + rad)}`,
                        i === 1 ? 'hi' : 'bs', 2.2])]);
