  ...[[18, 18], [42, 18], [42, 42], [18, 42]].map(([x, y]) => C(x, y, 3, 'hi')),  // galaxies, once closer together
  ...[[18, 18, 10, 10], [42, 18, 50, 10], [42, 42, 50, 50], [18, 42, 10, 50]]
    .map(([x, y, x2, y2]) => S(`M${x} ${y} L${x2} ${y2}`, 'bs', 1.8)),            // what keeps pushing them apart
