def('caesium_superoxide', () => [                              // CsO2 — one O-O radical anion, not two plain oxides
  facet('bs', 1.05), facet('hi', .48),
  S('M24 10 L32 10', 'ik', 1.8), C(24, 10, 3, CPK.O), C(32, 10, 3, CPK.O),
]);
