def('willow',  () => [S('M30 54 L30 20', 'lo', 5),
                      ...[-14, -6, 6, 14].map(dx => S(`M${30 + dx * .4} 22 Q${30 + dx} 34 ${30 + dx * 1.2} 52`, 'hi', 2))]);
