def('cochineal', () => [E(30, 32, 13, 9, 'gh'),
                        ...[20, 27, 34, 40].map(x => S(`M${x} 24 L${x} 40`, 'lo', 1.4)),
                        ...[[16, 24], [44, 24], [16, 40], [44, 40]].map(([x, y]) => S(`M${x} ${y} L${x < 30 ? 8 : 52} ${y < 32 ? 18 : 46}`, 'ik', 1.4))]);
def('carmine', () => [mound('bs', 46, 18, 17), ...granules('lo', 8, 111, [18, 34, 42, 46]),
                      C(44, 20, 4, 'bs')]);
