    const x = n(20 + 11 * Math.cos(a * Math.PI / 180)), y = n(32 + 11 * Math.sin(a * Math.PI / 180));
    return [S(`M20 32 L${x} ${y}`, 'ik', 1.6), C(x, y, 4.4, CPK.Cl)];
