  ...[0, 1, 2, 3].map(i => P(`M${20 + i * 7} ${46 - i * 8} L${25 + i * 7} ${46 - i * 8} L${25 + i * 7} 50 L${20 + i * 7} 50 Z`, 'bs')), // severity, scored higher
