  ...[[20, 22], [34, 20], [24, 34], [38, 34], [30, 46]].map(([x, y]) => [C(x, y, 6.4, 'bs'), C(x - 1.6, y - 1.6, 1.6, 'hi')]).flat(),  // pairs, chains, or a grape-like cluster — same cell either way
