  ...[[15, 45], [25, 30], [38, 23], [48, 12]].map(([x, y]) =>
    P(`M${x - 3.4} ${y + 3.4} L${x} ${y - 2.4} L${x + 3.4} ${y + 3.4} Z`, 'hi')),   // valves, letting it past once and once only
