    const t = (i + 1) / 8;
    const x0 = 11 + 9 * t, y0 = 54 - 45 * t, L = 29 - i * 3;
    return S(`M${n(x0)} ${n(y0)} L${n(x0 + L * 0.98)} ${n(y0 + L * 0.2)}`, 'ik', 1);
