  out.push(S('M40 52 Q47 44 44 34', 'hi', 2.4));                                      // raffia: the membrane peeled off the underside
  out.push(P('M3 58 L14 58 L12 50 L5 50 Z', 'ik'));                                   // the trunk it all comes off, dwarfed
