  ...[[20, 34], [19, 22], [31, 10]].map(([x, y]) => S(`M${x} ${y} L${n(x - 8)} ${n(y - 3)}`, 'gh', 1.6)),  // ions pumped in, water following
  ...[[46, 45], [51, 49], [42, 48]].map(([x, y]) => C(x, y, 2, 'lo')),  // uric acid, dry by the time it reaches the gut
