def('ember',       () => [...granules('lo', 9, 717, [14, 34, 46, 48]),
                          ...[[22, 38], [32, 42], [40, 36]].map(([x, y]) => E(x, y, 6, 4.4, 'hi')),
                          ...[0, 1, 2].map(i => S(`M${20 + i * 10} 30 Q${22 + i * 10} 24 ${20 + i * 10} 18`, 'gh', 1.1))]);
