def('mount_fuji',  () => [P('M2 52 L24 14 L36 14 L58 52 Z', 'lo'),
                          P('M24 14 L36 14 L41 22 L19 22 Z', 'hi'),           // the snow cap
                          // the older cones inside it, which is the real fact
                          ...[0, 1].map(i => S(`M${14 + i * 6} 52 L${27 + i * 2} ${26 + i * 6}`, 'gh', 1)),
                          ...[0, 1].map(i => S(`M${46 - i * 6} 52 L${33 - i * 2} ${26 + i * 6}`, 'gh', 1)),
                          S('M2 52 L58 52', 'bs', 1.6)]);

/* ART BATCH INSERTION POINT — new def() calls append here, above this line. */


const FAMILY = {
  mineral:  id => [facet('lo', .95), facet('bs', .6), ...granules('hi', 4, hash(id), [20, 26, 40, 38])],
  craft:    id => [P('M16 24 L44 24 L44 44 L16 44 Z', 'lo'), P('M20 28 L40 28 L40 40 L20 40 Z', 'bs')],
  grain:    id => [mound('bs', 46, 19, 17), ...granules('hi', 8, hash(id), [16, 32, 44, 46])],
  dish:     id => [round('lo', 40, 21, 9), E(30, 34, 13, 8, 'bs'), E(26, 31, 5, 3, 'hi')],
  ferment:  id => [vessel('lo'), wave('bs', 34, 4, 12), wave('hi', 30, 3, 11)],
  plant:    id => [stalk('lo', 30, 52, 20), leaf('bs', 22, 32, .7, -40), leaf('hi', 38, 32, .7, 40)],
  living:   id => [C(30, 32, 16, 'lo'), C(30, 32, 12, 'bs'), C(25, 27, 4.4, 'hi')],
  water:    id => [wave('lo', 42), wave('bs', 34), wave('hi', 26)],
  fire:     id => [flame('lo'), flame('bs', .68, 4)],
  molecule: id => {
    const { pts, shape } = backbone('ik', 3, 30, 32);
    return [shape, ...pts.map((p, i) => C(p[0], p[1], 4, i % 2 ? 'bs' : 'hi'))];
  },
};

/* ── build ────────────────────────────────────────────────────────────────*/

const out = {};
const missing = [];

for (const el of elements) {
  const cat = categoryOf(el);
  if (ART[el.id]) {
    out[el.id] = { c: cat, s: ART[el.id](), drawn: 1 };
  } else {
    out[el.id] = { c: cat, s: FAMILY[cat](el.id), drawn: 0 };
    missing.push(`${el.id} (${cat})`);
  }
}

/* Sanity: no shape may reference a role we cannot resolve. */
const ROLES = new Set(['lo', 'bs', 'hi', 'ik', 'gh', 'ground', 'discovery']);
const CATS = new Set(['mineral', 'craft', 'grain', 'dish', 'ferment', 'plant', 'living', 'water', 'fire', 'molecule']);
const badRoles = new Set();
const checkRole = r => {
  if (typeof r !== 'string') return;
  if (r.startsWith('#') || ROLES.has(r)) return;
  const [c, sub] = r.split('-');
  if (CATS.has(c) && ROLES.has(sub)) return;
  badRoles.add(r);
};
const walk = shapes => shapes.forEach(s => {
  if (!Array.isArray(s)) return;
  if (s[0] === 'g') return walk(s[4] || []);
  checkRole(s[s[0] === 'c' ? 4 : s[0] === 'e' ? 5 : 2]);
});
for (const v of Object.values(out)) walk(v.s);
/* The bedrock defs have to be exercised BEFORE check exits, or they are never
   run at all: four separate agents drawing them found that `check` could not
   see a bed_ id — not its roles, not its fingerprint, not even a throw in the
   drawing body — because the exit below fired first and the loop that invokes
   them came after. A def that was broken would have passed check and failed
   only at build. They are invoked here, and their shapes join the same sameness
   report everything else is held to. */
const BED_CAT = {
  particle: 'molecule', molecule: 'molecule', monomer: 'molecule', polymer: 'molecule',
  structure: 'living', assembly: 'living', cell: 'living', blood_cell: 'living',
  tissue: 'living', tube: 'living', bone: 'living', fluid: 'living',
  organ: 'living', joint: 'living', eggpart: 'living',
};
const BEDROCK = JSON.parse(readFileSync(join(root, 'data/bedrock.json'), 'utf8'));
const bedOut = {};
for (const c of BEDROCK.compounds) {
  if (!ART[c.id]) continue;
  bedOut[c.id] = { c: BED_CAT[c.tier] || 'craft', s: ART[c.id]() };
}
const bedMissing = BEDROCK.compounds.filter(c => !ART[c.id]).map(c => c.id);
console.log(`\n  bedrock: ${Object.keys(bedOut).length} of ${BEDROCK.compounds.length} compounds drawn`);
for (const v of Object.values(bedOut)) walk(v.s);   // roles, same as the elements

/* A shape list must hold shapes. `.map(y => S(...)).flat()` spreads each S()
   into loose "s", "M22 14 L38 14", "lo", 2.4 entries, and both walk() here and
   the renderer skip non-arrays in silence — so the drawing passes every check
   and quietly loses the shapes. One of the 205 shipped that way and was caught
   by an agent reading another agent's code, not by any tool. */
const malformed = [];
for (const [id, v] of Object.entries({ ...out, ...bedOut }))
  if (v.s.some(x => !Array.isArray(x))) malformed.push(id);
if (malformed.length) {
  console.error(`\n  shape lists with loose entries (a stray .flat()?): ${malformed.join(', ')}`);
  process.exit(1);
}



const drawn = elements.length - missing.length;
console.log(`  ${drawn}/${elements.length} items drawn by hand, ${missing.length} on the family fallback`);

/* A shape painted in the card's own colour is a hole, not a shape, and nothing
 * looking at the drawing can tell — it simply is not there. mineral's `lo` was
 * derived two Munsell value steps below its base, which for the workhorse soil
 * chip landed exactly on the card: 735 drawings had at least one shape they
 * never showed, and hadron lost 24 of its 27. palette.mjs now refuses to hand
 * out a tint equal to the card, so this counts what got through anyway — a
 * hard-coded hex, or a new surface that collides with an existing role. */
{
  const palette = JSON.parse(readFileSync(join(root, 'data/palette.json'), 'utf8'));
  const card = palette.surfaces.panel.hex.toUpperCase();
  const role = {};
  for (const [k, v] of Object.entries(palette.categories)) {
    role[k] = { bs: v.hex.toUpperCase(), hi: v.hi.hex.toUpperCase(), lo: v.lo.hex.toUpperCase() };
  }
  const paints = (sh, acc) => {
    if (sh[0] === 'g') sh[4].forEach(x => paints(x, acc));
    else acc.push(sh[0] === 'c' ? sh[4] : sh[0] === 'e' ? sh[5] : sh[2]);
    return acc;
  };
  const blind = [];
  for (const [id, d] of Object.entries({ ...out, ...bedOut })) {
    const n = paints(['g', 0, 0, 0, d.s], []).filter(r =>
      typeof r === 'string' &&
      (r.toUpperCase() === card || (role[d.c] && role[d.c][r] === card))).length;
    if (n) blind.push([id, n]);
  }
  if (blind.length) {
    blind.sort((a, b) => b[1] - a[1]);
    console.log(`\n  ${blind.length} drawing(s) paint a shape in the card colour and cannot show it:`);
    for (const [id, n] of blind.slice(0, 12)) console.log(`    ${id} — ${n} shape(s)`);
  } else {
    console.log('  no shape is painted in the card colour');
  }

  /* The card colour is not the only thing a shape can vanish into. `ik` is
   * #D8C8B1 and so is craft's `hi`, so a symbol drawn in ik on top of a hi
   * panel is painted in the panel's own colour — which is how a pound sign
   * and a dollar sign both shipped as blank notes.
   *
   * Two roles merely SHARING a hex is not the fault and flagging that gives
   * 1,149 hits, nearly all of them harmless: gh over here and lo over there
   * never meet. The fault is one shape drawn ON TOP of another in the same
   * colour, so the test is containment — a later shape whose box sits inside
   * an earlier same-coloured one — which is the case that actually vanishes.
   */
  const SURF = { ik: palette.surfaces.ink.hex.toUpperCase(),
                 gh: palette.surfaces.rule.hex.toUpperCase(),
                 ground: palette.surfaces.ground.hex.toUpperCase() };
  const box = (sh) => {
    const nums = [];
    const eat = (v) => { if (typeof v === 'number') nums.push(v);
      else if (typeof v === 'string') for (const m of v.matchAll(/-?\d+(?:\.\d+)?/g)) nums.push(+m[0]); };
    if (sh[0] === 'p' || sh[0] === 's') eat(sh[1]);
    else if (sh[0] === 'c') { const [, cx, cy, r] = sh; return [cx - r, cy - r, cx + r, cy + r]; }
    else if (sh[0] === 'e') { const [, cx, cy, rx, ry] = sh; return [cx - rx, cy - ry, cx + rx, cy + ry]; }
    if (!nums.length) return null;
    const xs = nums.filter((_, i) => i % 2 === 0), ys = nums.filter((_, i) => i % 2 === 1);
    if (!xs.length || !ys.length) return null;
    return [Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys)];
  };
  const inside = (a, b) => a && b && a[0] >= b[0] - 1 && a[1] >= b[1] - 1 && a[2] <= b[2] + 1 && a[3] <= b[3] + 1;
  const area = (b) => b ? (b[2] - b[0]) * (b[3] - b[1]) : 0;
  const flat = (list, acc) => { for (const sh of list) sh[0] === 'g' ? flat(sh[4], acc) : acc.push(sh); return acc; };
  const roleOf = (sh) => sh[0] === 'c' ? sh[4] : sh[0] === 'e' ? sh[5] : sh[2];
  const buried = [];
  for (const [id, d] of Object.entries({ ...out, ...bedOut })) {
    const shapes = flat(d.s, []);
    const hex = (r) => SURF[r] ?? (role[d.c] && role[d.c][r]);
    for (let i = 0; i < shapes.length; i++) {
      const under = shapes[i];
      if (under[0] !== 'p' && under[0] !== 'c' && under[0] !== 'e') continue;  // fills only
      const ub = box(under), uh = hex(roleOf(under));
      if (!uh || area(ub) < 60) continue;
      for (let j = i + 1; j < shapes.length; j++) {
        const over = shapes[j];
        if (hex(roleOf(over)) !== uh) continue;
        if (roleOf(over) === roleOf(under)) continue;   // same role is deliberate
        if (inside(box(over), ub)) { buried.push(`${id}: ${roleOf(over)} on ${roleOf(under)}, both ${uh}`); break; }
      }
    }
  }
  const uniq = [...new Set(buried)];
  if (uniq.length) {
    console.log(`\n  ${uniq.length} drawing(s) paint a shape on top of another in the same colour:`);
    for (const c of uniq.slice(0, 12)) console.log(`    ${c}`);
    if (uniq.length > 12) console.log(`    ... and ${uniq.length - 12} more`);
  } else {
    console.log('  no shape is buried in another of its own colour');
  }
}

const byCat = {};
for (const [id, v] of Object.entries(out)) {
  byCat[v.c] = byCat[v.c] || { drawn: 0, total: 0 };
  byCat[v.c].total++; if (v.drawn) byCat[v.c].drawn++;
}
for (const [c, v] of Object.entries(byCat).sort((a, b) => b[1].total - a[1].total)) {
  const bar = '#'.repeat(Math.round((v.drawn / v.total) * 20)).padEnd(20, '.');
  console.log(`    ${c.padEnd(9)} ${bar} ${v.drawn}/${v.total}`);
}

if (badRoles.size) {
  console.error(`\n  unresolvable roles: ${[...badRoles].join(', ')}`);
  process.exit(1);
}

/* ── sameness check ───────────────────────────────────────────────────────
 * The way a 226-item set dies is not by any one item being bad. It is by
 * forty of them quietly becoming the same vessel with a different label. So
 * we measure it: reduce each item to a coarse structural fingerprint and
 * report any pair inside a category that is too close.
 */
function fingerprint(shapes) {
  const parts = [];
  const walk = arr => arr.forEach(s => {
    if (!Array.isArray(s)) return;
    if (s[0] === 'g') return walk(s[4] || []);
    const q = v => Math.round(v / 6);                    // 6-unit buckets
    if (s[0] === 'c') parts.push(`c${q(s[1])},${q(s[2])},${q(s[3])}`);
    else if (s[0] === 'e') parts.push(`e${q(s[1])},${q(s[2])},${q(s[3])},${q(s[4])}`);
    else parts.push(s[0] + s[1].replace(/[\d.]+/g, m => q(+m)));
  });
  walk(shapes);
  return parts.sort();
}

function similarity(a, b) {
  const A = new Set(a), B = new Set(b);
  let hit = 0;
  for (const x of A) if (B.has(x)) hit++;
  return (2 * hit) / (A.size + B.size);
}

function samenessReport() {
  const fp = {};
  // Bedrock drawings are compared too, against each other and against every
  // element in the same category. Eight agents drew 205 of them and none could
  // see another's work; a white blood cell drawn twice as "circle with a lobed
  // nucleus" is exactly what no single agent can catch.
  for (const [id, v] of Object.entries(out)) fp[id] = { c: v.c, f: fingerprint(v.s) };
  for (const [id, v] of Object.entries(bedOut)) fp[id] = { c: v.c, f: fingerprint(v.s) };
  const ids = Object.keys(fp);
  const pairs = [];
  for (let i = 0; i < ids.length; i++) {
    for (let j = i + 1; j < ids.length; j++) {
      if (fp[ids[i]].c !== fp[ids[j]].c) continue;
      const sim = similarity(fp[ids[i]].f, fp[ids[j]].f);
      if (sim >= 0.72) pairs.push([sim, ids[i], ids[j], fp[ids[i]].c]);
    }
  }
  pairs.sort((a, b) => b[0] - a[0]);
  return pairs;
}

const same = samenessReport();
if (same.length) {
  console.log(`\n  ${same.length} pair(s) too alike to tell apart at shelf size:`);
  for (const [sim, a, b, c] of same.slice(0, 40)) {
    console.log(`    ${(sim * 100).toFixed(0)}%  ${c.padEnd(9)} ${a}  ~  ${b}`);
  }
  if (same.length > 40) console.log(`    ... and ${same.length - 40} more`);
} else {
  console.log('\n  no two items in a category are too alike');
}

if (process.argv[2] === 'check') {
  if (missing.length) console.log(`\n  still to draw:\n    ${missing.join('\n    ')}`);
  if (bedMissing.length) console.log(`  bedrock still to draw: ${bedMissing.length}`);
  process.exit(same.length ? 1 : 0);
}

/* Strip the authoring flag; the game only needs category and shapes. */
const ship = {};
for (const [id, v] of Object.entries(out)) ship[id] = { c: v.c, s: v.s };
for (const [id, fn] of Object.entries(VERB)) ship['verb_' + id] = { c: 'craft', s: fn() };

/* The composition tree draws from the same book. Its 205 compounds are not
   elements, so the loop above never reached them and every one of them
   rendered as an empty hexagon — "Bee is made of" listed Tracheal System,
   Malpighian Tubules and Ecdysone as blank shapes. A def() keyed on a bed_ id
   is emitted here instead, categorised by tier so the palette matches what the
   thing actually is. Anything still undrawn keeps the hexagon, which is the
   honest fallback rather than a wrong picture. */
Object.assign(ship, bedOut);

/* Interface marks. The gear and the stack render as full-colour emoji on some
   platforms and as text glyphs on others, which is exactly the inconsistency
   leaving emoji behind was meant to end. */
ship.ui_settings = { c: 'craft', s: [
  ...Array.from({ length: 8 }, (_, i) => {
    const a = (i * Math.PI) / 4;
    return S(`M${n(30 + 13 * Math.cos(a))} ${n(30 + 13 * Math.sin(a))} ` +
             `L${n(30 + 21 * Math.cos(a))} ${n(30 + 21 * Math.sin(a))}`, 'ik', 5);
  }),
  C(30, 30, 15, 'ik'), C(30, 30, 6.5, 'ground'),
] };
ship.ui_tidy = { c: 'craft', s: [
  S('M12 20 L48 20', 'ik', 4), S('M12 30 L48 30', 'ik', 4), S('M12 40 L40 40', 'ik', 4),
] };
ship.ui_undo = { c: 'craft', s: [
  S('M40 18 A15 15 0 1 1 18 30', 'ik', 5),
  S('M18 30 L25 23', 'ik', 5), S('M18 30 L26 35', 'ik', 5),
] };
ship.ui_nudge = { c: 'craft', s: [
  S('M18 40 L42 20', 'ik', 4), S('M33.8 34.6 L26.2 25.4', 'ik', 4),
  C(18, 40, 8, 'ik'), C(42, 20, 8, 'ik'), C(18, 40, 3, 'ground'), C(42, 20, 3, 'ground'),
] };
ship.ui_scan = { c: 'craft', s: [
  S('M10 22 Q10 18 14 18 L21 18 L24 14 L36 14 L39 18 L46 18 Q50 18 50 22 L50 42 Q50 46 46 46 L14 46 Q10 46 10 42 Z', 'ik', 3.5),
  C(30, 32, 8, 'ik'), C(30, 32, 4, 'ground'),
] };
ship.ui_amino = { c: 'craft', s: [
  S('M12 40 L22 26 L34 34 L48 20', 'ik', 3.4),
  C(12, 40, 4, 'bs'), C(48, 20, 4, 'hi'),
] };
ship.ui_ladder = { c: 'craft', s: [
  S('M18 8 L18 52', 'ik', 3), S('M42 8 L42 52', 'ik', 3),
  ...[14, 26, 38, 50].map(y => S(`M18 ${y} L42 ${y}`, 'ik', 3)),
] };
// The GHS "health hazard" pictogram — a torso with a starburst radiating from
// inside the chest. It is the international mark for carcinogens, mutagens and
// reproductive toxins, which is exactly the claim being made. Deliberately not
// the biohazard trefoil (that means infectious material) and not the radiation
// trefoil (which this badge already uses, and which wins the slot over this).
ship.ui_carcinogen = { c: 'craft', s: [
  S('M30 10 A7 7 0 1 1 29.9 10', 'ik', 3),                                    // head
  S('M18 44 Q18 24 30 24 Q42 24 42 44', 'ik', 3),                             // shoulders and torso
  ...Array.from({ length: 8 }, (_, i) => {
    const a = (i * Math.PI) / 4;
    return S(`M${n(30 + 3.5 * Math.cos(a))} ${n(36 + 3.5 * Math.sin(a))} ` +
             `L${n(30 + 9 * Math.cos(a))} ${n(36 + 9 * Math.sin(a))}`, 'ik', 2.4);
  }),                                                                          // the burst inside the chest
  C(30, 36, 3.2, 'ik'),
] };
// Free play, as an open padlock: the shackle is lifted clear on one side
// rather than seated in the body. Circles and one arc only, the same
// restraint as ui_eye — a drawn keyhole would not survive 16px.
ship.ui_freeplay = { c: 'craft', s: [
  S('M38 31 L38 22 A8 8 0 0 0 22 22', 'ik', 3),
  P('M17 31 L43 31 Q45 31 45 33 L45 46 Q45 48 43 48 L17 48 Q15 48 15 46 L15 33 Q15 31 17 31 Z', 'bs'),
  C(30, 39, 3.2, 'ground'),
] };
ship.ui_eye = { c: 'craft', s: [
  S('M8 30 Q30 12 52 30 Q30 48 8 30 Z', 'ik', 3), C(30, 30, 7, 'ik'), C(30, 30, 3, 'ground'),
] };
// The aside pane's own tabs, converted from text to icons ("could the side
// panel 'shelf' and 'elements' turn to just icons?" — asked more than once).
// Three items sitting on a line, for a shelf holding what you've found.
ship.ui_shelf = { c: 'craft', s: [
  S('M10 44 L50 44', 'ik', 3.5), C(20, 34, 4, 'bs'), C(32, 30, 4, 'hi'), C(44, 36, 4, 'bs'),
] };
// A plain list — bullet and rule, three times — distinct from ui_table's
// grid, since this tab is the flat catalogue, not the periodic chart.
ship.ui_elements = { c: 'craft', s: [
  C(9, 17, 2.4, 'ik'), S('M17 17 L48 17', 'ik', 3.2),
  C(9, 30, 2.4, 'ik'), S('M17 30 L48 30', 'ik', 3.2),
  C(9, 43, 2.4, 'ik'), S('M17 43 L48 43', 'ik', 3.2),
] };
// A paw: one pad, three toes — geometric circles only, matching ui_eye's
// restraint rather than a literal illustrated paw print.
ship.ui_animals = { c: 'craft', s: [
  C(30, 38, 9, 'bs'), C(17, 22, 5, 'hi'), C(30, 15, 5, 'hi'), C(43, 22, 5, 'hi'),
] };
ship.ui_shutter = { c: 'craft', s: [
  // A single still capture, not the live scan — a shutter ring, not a
  // camera body, so it doesn't just repeat ui_scan's silhouette.
  ['s', 'M30 8 A22 22 0 1 1 29.9 8', 'ik', 4],
  C(30, 30, 9, 'ik'),
] };
ship.ui_gallery = { c: 'craft', s: [
  // Two overlapping photo frames — picking from what already exists,
  // rather than pointing a lens at something new.
  S('M12 14 L40 14 L40 42 L12 42 Z', 'ik', 3),
  S('M20 22 L48 22 L48 50 L20 50 Z', 'ik', 3),
  C(28, 32, 3, 'ik'),
] };
ship.ui_digits = { c: 'craft', s: [
  // A barcode's own bars, varying width — typing the number under it is
  // the one path here that needs no camera at all.
  ...[[10, 5], [16, 3], [21, 6], [28, 3], [33, 5], [38, 3], [43, 6], [48, 4]].map(([x, w]) =>
    P(`M${x} 12 L${x + w} 12 L${x + w} 40 L${x} 40 Z`, 'ik')),
] };
ship.ui_table = { c: 'craft', s: [
  // A grid of element tiles, not a gear — the periodic-table toggle used to
  // share a literal gear glyph with the Settings button, which is exactly
  // the "these two buttons look the same" report this replaces.
  ...[12, 24, 36].flatMap(x => [12, 24, 36].map(y =>
    P(`M${x} ${y} L${x + 9} ${y} L${x + 9} ${y + 9} L${x} ${y + 9} Z`, 'ik'))),
] };
ship.ui_motes = { c: 'craft', s: [
  // A line with three dots travelling along it, shrinking as they go —
  // the same thing drawLinksNow() actually draws on the bench, in
  // miniature, so the toolbar icon reads as a preview of the toggle
  // rather than an arbitrary symbol standing in for it.
  S('M8 46 Q22 46 30 30 Q38 14 52 14', 'ik', 3),
  C(14, 44, 4.2, 'ik'), C(30, 30, 3.4, 'ik'), C(46, 16, 2.6, 'ik'),
] };
ship.ui_consolidate = { c: 'craft', s: [
  // Two duplicate outlines folding into one solid card — the toolbar
  // preview of what the "one card per thing" toggle actually does to
  // the bench, the same way ui_motes previews the dots it turns on.
  S('M8 12 L22 12 L22 26 L8 26 Z', 'ik', 2.4),
  S('M14 18 L28 18 L28 32 L14 32 Z', 'ik', 2.4),
  S('M30 22 L40 22', 'ik', 3.2),
  P('M42 12 L56 12 L56 26 L42 26 Z', 'ik'),
] };
ship.ui_circle = { c: 'craft', s: [
  C(30, 30, 4, 'ik'),
  ...Array.from({ length: 6 }, (_, i) => {
    const a = (i / 6) * Math.PI * 2;
    const x = n(30 + 16 * Math.cos(a)), y = n(30 + 16 * Math.sin(a));
    return [S(`M30 30 L${x} ${y}`, 'gh', 1.6), C(x, y, 3, 'ik')];
  }).flat(),
] };

/* One water MOLECULE, not a body of water. It is what leaves in a condensation
   reaction, and the whole point of showing it is that it is a molecule. */
ship.mol_water = { c: 'molecule', s: [
  S('M30 34 L16 22', 'ik', 3), S('M30 34 L44 22', 'ik', 3),
  C(30, 34, 11, CPK.O), C(16, 22, 6.5, CPK.H), C(44, 22, 6.5, CPK.H),
] };

writeFileSync(join(root, 'data/art.json'), JSON.stringify(ship) + '\n');
const kb = (JSON.stringify(ship).length / 1024).toFixed(1);
console.log(`\n  wrote data/art.json — ${kb} kB`);
